class ReportingPortalException(Exception):
    """Base exception for the taf.sw.reporting_portal package."""


class SendReportError(ReportingPortalException):
    """Exception raised if sending a report to Reporting Portal failed."""


class CommandLineException(ReportingPortalException):
    """Exception raised if command line failed somehow."""


class FileDoesNotExist(ReportingPortalException):
    """Exception raised when a file specified by the user does not exist."""


class WrongDataFormat(ReportingPortalException):
    """Exception raised when user provided wrong data format."""


class HostConnectionError(ReportingPortalException):
    """Exception raised when FSM IP scan fails"""


class EmptySuiteException(ReportingPortalException):
    """Exception raised when report was created based on empty suite"""


class HTTPConnectionException(ReportingPortalException):
    """Exception raised when response code is not 200"""


class TestInstanceNotExistent(ReportingPortalException):
    """Exception raised when test instance does not exist in RP"""

    __test__ = False


class WrongMessageId(ReportingPortalException):
    """Exception raised when test instance does not exist in RP"""


class IncompleteData(ReportingPortalException):
    """Exception raised when data provided for CRT check is not complete"""


class NotSupportedProductException(ReportingPortalException):
    """Exception raised when trying to create file collector for not supported product"""


class ElasticCluseterBadStatusException(ReportingPortalException):
    """Exception raised when elasticsearch cluster is not reachable or in bad health"""


class WrongParameterSet(ReportingPortalException):
    """Exception raised when user provided wrong set of parameters."""
